=== FILE: tb_mac8.v ===
// Self-checking testbench for mac8 with a reference model written from
// interface_spec.md (clauses MAC-RESET, MAC-CLEAR, MAC-ACC, MAC-HOLD,
// MAC-SAT, MAC-STICKY), not from the RTL. Every acc/sat value is compared
// after every rising edge; directed scenarios also compare literal values
// computed from the specification; corner counters must be nonzero.
`timescale 1ns / 1ps
module tb_mac8;
    // ------------------------------------------------------------------
    // Clock and DUT
    // ------------------------------------------------------------------
    reg clk;
    initial clk = 1'b0;
    always #5 clk = ~clk;

    reg        rst_n;
    reg        clr;
    reg        en;
    reg  [7:0] a;
    reg  [7:0] b;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk   (clk),
        .rst_n (rst_n),
        .clr   (clr),
        .en    (en),
        .a     (a),
        .b     (b),
        .acc   (acc),
        .sat   (sat)
    );

    // ------------------------------------------------------------------
    // Reference model state and bookkeeping
    // ------------------------------------------------------------------
    reg [23:0] m_acc;
    reg        m_sat;
    reg        m_valid;      // state is defined only after the first reset
    reg [31:0] r_prod;
    reg [31:0] r_total;

    integer n_pass;
    integer n_fail;
    integer n_cycle;
    integer n_print;
    integer seed;
    integer i;
    reg     done;

    // corner counters
    integer cov_sat_new;     // saturation with flag previously 0
    integer cov_sat_again;   // saturating accumulate with flag already 1
    integer cov_exact_max;   // sum exactly 0xFFFFFF, no saturation
    integer cov_clr_en;      // clear offered together with an accumulate
    integer cov_clr_sat;     // clear while saturated
    integer cov_rst_en;      // reset offered together with an accumulate
    integer cov_rst_sat;     // reset while saturated
    integer cov_hold;        // en low, clr low
    integer cov_hold_sat;    // hold while saturated
    integer cov_zero_sat;    // zero-product accumulate while saturated
    integer cov_max_prod;    // product 255*255

    reg [8*64-1:0] nonce;
    reg            have_nonce;

    // random-phase stimulus
    reg [31:0] ctl;
    reg [31:0] opa;
    reg        rr, cc, ee;
    reg [7:0]  aa, bb;

    localparam integer N_RANDOM = 20000;

    // ------------------------------------------------------------------
    // Reference model: one step per rising edge, inputs as sampled there
    // ------------------------------------------------------------------
    task model_step;
        begin
            r_prod  = {24'd0, a} * {24'd0, b};     // unsigned 8x8
            r_total = {8'd0, m_acc} + r_prod;      // no wrap in 32 bits
            if (!rst_n) begin                       // MAC-RESET
                if (m_valid && en)    cov_rst_en  = cov_rst_en + 1;
                if (m_valid && m_sat) cov_rst_sat = cov_rst_sat + 1;
                m_acc   = 24'd0;
                m_sat   = 1'b0;
                m_valid = 1'b1;
            end else if (!m_valid) begin
                // before the first reset the state is not specified
            end else if (clr) begin                 // MAC-CLEAR: clear wins
                if (en)    cov_clr_en  = cov_clr_en + 1;
                if (m_sat) cov_clr_sat = cov_clr_sat + 1;
                m_acc = 24'd0;
                m_sat = 1'b0;
            end else if (en) begin                  // MAC-ACC
                if (r_prod == 32'd65025) cov_max_prod = cov_max_prod + 1;
                if (r_total > 32'h00FFFFFF) begin   // MAC-SAT
                    if (m_sat) cov_sat_again = cov_sat_again + 1;
                    else       cov_sat_new   = cov_sat_new + 1;
                    m_acc = 24'hFFFFFF;
                    m_sat = 1'b1;
                end else begin
                    if (r_total == 32'h00FFFFFF) cov_exact_max = cov_exact_max + 1;
                    if (m_sat) cov_zero_sat = cov_zero_sat + 1;
                    m_acc = r_total[23:0];
                    // MAC-STICKY: m_sat keeps its value
                end
            end else begin                          // MAC-HOLD
                cov_hold = cov_hold + 1;
                if (m_sat) cov_hold_sat = cov_hold_sat + 1;
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Scoreboard compare, every cycle, both outputs
    // ------------------------------------------------------------------
    task check_outputs;
        begin
            if (m_valid) begin
                if (acc === m_acc) begin
                    n_pass = n_pass + 1;
                end else begin
                    n_fail = n_fail + 1;
                    if (n_print < 20) begin
                        $display("MISMATCH acc cycle %0d: rst_n=%b clr=%b en=%b a=%h b=%h | acc got %h exp %h | sat got %b exp %b",
                                 n_cycle, rst_n, clr, en, a, b, acc, m_acc, sat, m_sat);
                        n_print = n_print + 1;
                    end
                end
                if (sat === m_sat) begin
                    n_pass = n_pass + 1;
                end else begin
                    n_fail = n_fail + 1;
                    if (n_print < 20) begin
                        $display("MISMATCH sat cycle %0d: rst_n=%b clr=%b en=%b a=%h b=%h | acc got %h exp %h | sat got %b exp %b",
                                 n_cycle, rst_n, clr, en, a, b, acc, m_acc, sat, m_sat);
                        n_print = n_print + 1;
                    end
                end
            end
        end
    endtask

    // One clock cycle: drive away from the sampling edge, step the model at
    // the edge, compare after the design has settled.
    task cyc(input t_r, input t_c, input t_e, input [7:0] t_a, input [7:0] t_b);
        begin
            @(negedge clk);
            rst_n = t_r;
            clr   = t_c;
            en    = t_e;
            a     = t_a;
            b     = t_b;
            @(posedge clk);
            n_cycle = n_cycle + 1;
            model_step;
            #1;
            check_outputs;
        end
    endtask

    // Directed check against a literal value computed from the specification.
    task expect_now(input [23:0] e_acc, input e_sat, input integer id);
        begin
            if (acc === e_acc && sat === e_sat) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                $display("DIRECTED CHECK %0d FAILED at cycle %0d: acc got %h exp %h | sat got %b exp %b",
                         id, n_cycle, acc, e_acc, sat, e_sat);
            end
        end
    endtask

    task require_corner(input integer count, input integer id);
        begin
            if (count > 0) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                $display("CORNER %0d NOT REACHED: the clean comparisons say nothing about it", id);
            end
        end
    endtask

    task print_verdict;
        integer k;
        begin
            $write("NIRMAAN-SIM ");
            for (k = 63; k >= 0; k = k - 1)
                if (nonce[k*8 +: 8] != 8'd0) $write("%c", nonce[k*8 +: 8]);
            $write(" %0d passed, %0d failed\n", n_pass, n_fail);
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin
        #10000000;
        if (!done) begin
            done = 1'b1;
            n_fail = n_fail + 1;
            $display("WATCHDOG: simulation did not complete");
            print_verdict;
            $finish;
        end
    end

    // ------------------------------------------------------------------
    // Main sequence
    // ------------------------------------------------------------------
    initial begin
        done    = 1'b0;
        rst_n   = 1'b0;
        clr     = 1'b0;
        en      = 1'b0;
        a       = 8'd0;
        b       = 8'd0;
        m_acc   = 24'd0;
        m_sat   = 1'b0;
        m_valid = 1'b0;
        n_pass  = 0;
        n_fail  = 0;
        n_cycle = 0;
        n_print = 0;
        cov_sat_new = 0;  cov_sat_again = 0; cov_exact_max = 0;
        cov_clr_en  = 0;  cov_clr_sat   = 0; cov_rst_en    = 0;
        cov_rst_sat = 0;  cov_hold      = 0; cov_hold_sat  = 0;
        cov_zero_sat = 0; cov_max_prod  = 0;

        nonce = 0;
        have_nonce = 1'b0;
        if      ($value$plusargs("NIRMAAN_NONCE=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce))         have_nonce = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce))         have_nonce = 1'b1;

        seed = 32'h5EEDAC24;
        if ($value$plusargs("MAC8_SEED=%d", seed)) ;
        $display("tb_mac8: random seed %0d", seed);

        // S1 MAC-RESET: reset wins over accumulate and over clear
        cyc(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        cyc(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);
        cyc(1'b0, 1'b0, 1'b0, 8'h00, 8'h00);
        expect_now(24'd0, 1'b0, 1);

        // S2 MAC-ACC: basic and unsigned operand reading
        cyc(1'b1, 1'b0, 1'b1, 8'd3, 8'd4);     expect_now(24'd12, 1'b0, 2);
        cyc(1'b1, 1'b0, 1'b1, 8'd5, 8'd6);     expect_now(24'd42, 1'b0, 3);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'h01);   expect_now(24'd297, 1'b0, 4);
        cyc(1'b1, 1'b0, 1'b1, 8'h80, 8'h01);   expect_now(24'd425, 1'b0, 5);
        cyc(1'b1, 1'b0, 1'b1, 8'h01, 8'h80);   expect_now(24'd553, 1'b0, 6);
        cyc(1'b1, 1'b0, 1'b1, 8'h00, 8'hFF);   expect_now(24'd553, 1'b0, 7);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);   expect_now(24'd65578, 1'b0, 8);

        // S3 MAC-HOLD: en low with non-zero operands
        cyc(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        cyc(1'b1, 1'b0, 1'b0, 8'h12, 8'h34);
        cyc(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        expect_now(24'd65578, 1'b0, 9);

        // S4 MAC-CLEAR: clear wins over accumulate at the same edge
        cyc(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);   expect_now(24'd0, 1'b0, 10);
        cyc(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);   expect_now(24'd0, 1'b0, 11);

        // S5 exact reach of 0xFFFFFF: 258*65025 + 255*3 = 0xFFFFFF, no flag
        repeat (258) cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        expect_now(24'hFFFD02, 1'b0, 12);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'h03);   expect_now(24'hFFFFFF, 1'b0, 13);
        cyc(1'b1, 1'b0, 1'b1, 8'h00, 8'h55);   expect_now(24'hFFFFFF, 1'b0, 14);
        cyc(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);   expect_now(24'hFFFFFF, 1'b0, 15);

        // S6 MAC-SAT by one
        cyc(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);   expect_now(24'hFFFFFF, 1'b1, 16);

        // S7 MAC-STICKY: hold, zero product, saturating again
        cyc(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        cyc(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);   expect_now(24'hFFFFFF, 1'b1, 17);
        cyc(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);   expect_now(24'hFFFFFF, 1'b1, 18);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'h00);   expect_now(24'hFFFFFF, 1'b1, 19);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);   expect_now(24'hFFFFFF, 1'b1, 20);
        cyc(1'b1, 1'b0, 1'b1, 8'h00, 8'h01);   expect_now(24'hFFFFFF, 1'b1, 21);

        // S8 clear while saturated, with accumulate offered; then accumulate
        cyc(1'b1, 1'b1, 1'b1, 8'h01, 8'h01);   expect_now(24'd0, 1'b0, 22);
        cyc(1'b1, 1'b0, 1'b1, 8'h02, 8'h03);   expect_now(24'd6, 1'b0, 23);
        cyc(1'b1, 1'b0, 1'b0, 8'h02, 8'h03);   expect_now(24'd6, 1'b0, 24);

        // S9 overshoot by a large product: wrapped sum would be 0x010003
        cyc(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);   expect_now(24'd0, 1'b0, 25);
        repeat (258) cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        expect_now(24'hFFFD02, 1'b0, 26);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);   expect_now(24'hFFFFFF, 1'b1, 27);

        // S10 reset while saturated, with accumulate offered
        cyc(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);   expect_now(24'd0, 1'b0, 28);
        cyc(1'b1, 1'b0, 1'b1, 8'd7, 8'd9);     expect_now(24'd63, 1'b0, 29);
        cyc(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);   expect_now(24'd63, 1'b0, 30);

        // S11 overshoot just past the limit: 0xFFFD02 + 1020 > 0xFFFFFF
        cyc(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);   expect_now(24'd0, 1'b0, 31);
        repeat (258) cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        cyc(1'b1, 1'b0, 1'b1, 8'hFF, 8'h04);   expect_now(24'hFFFFFF, 1'b1, 32);

        // S12 reset in the middle of operation; reset together with clear
        cyc(1'b0, 1'b0, 1'b1, 8'h10, 8'h10);   expect_now(24'd0, 1'b0, 33);
        cyc(1'b1, 1'b0, 1'b1, 8'h10, 8'h10);   expect_now(24'd256, 1'b0, 34);
        cyc(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);   expect_now(24'd0, 1'b0, 35);
        cyc(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);   expect_now(24'd0, 1'b0, 36);

        // Random phase: scoreboard compares every cycle
        for (i = 0; i < N_RANDOM; i = i + 1) begin
            ctl = $random(seed);
            opa = $random(seed);
            rr = (ctl[11:0] != 12'd0);       // reset about 1 in 4096
            cc = (ctl[22:12] == 11'd0);      // clear about 1 in 2048
            ee = (ctl[24:23] != 2'd0);       // accumulate 3 in 4
            case (opa[1:0])
                2'd0:    aa = opa[15:8];
                2'd1:    aa = 8'hFF;
                2'd2:    aa = {4'hF, opa[11:8]};
                default: aa = (opa[9:8] == 2'd0) ? 8'h00 : opa[15:8];
            endcase
            case (opa[3:2])
                2'd0:    bb = opa[23:16];
                2'd1:    bb = 8'hFF;
                2'd2:    bb = {4'hF, opa[19:16]};
                default: bb = (opa[17:16] == 2'd0) ? 8'h00 : opa[23:16];
            endcase
            cyc(rr, cc, ee, aa, bb);
        end

        // Every named corner must have been reached
        require_corner(cov_sat_new,   1);
        require_corner(cov_sat_again, 2);
        require_corner(cov_exact_max, 3);
        require_corner(cov_clr_en,    4);
        require_corner(cov_clr_sat,   5);
        require_corner(cov_rst_en,    6);
        require_corner(cov_rst_sat,   7);
        require_corner(cov_hold,      8);
        require_corner(cov_hold_sat,  9);
        require_corner(cov_zero_sat,  10);
        require_corner(cov_max_prod,  11);

        $display("tb_mac8: %0d cycles; corners sat_new=%0d sat_again=%0d exact_max=%0d clr_en=%0d clr_sat=%0d rst_en=%0d rst_sat=%0d hold=%0d hold_sat=%0d zero_sat=%0d max_prod=%0d",
                 n_cycle, cov_sat_new, cov_sat_again, cov_exact_max, cov_clr_en, cov_clr_sat,
                 cov_rst_en, cov_rst_sat, cov_hold, cov_hold_sat, cov_zero_sat, cov_max_prod);

        if (!have_nonce) begin
            n_fail = n_fail + 1;
            $display("tb_mac8: no nonce plusarg found");
        end

        if (!done) begin
            done = 1'b1;
            print_verdict;
            $finish;
        end
    end
endmodule
=== END FILE ===
